#include "crew_sequence.h"
#include <cstdio>
#include <memory>
using namespace tactics;
__attribute__((noinline)) static Proposal selected(World&w){Proposal p;p.valid=true;p.crew_clear_certified=w.self.id<0;p.action.kind=Kind::Move;p.action.at=w.self.pos;p.mission.phase=static_cast<Phase>(w.round%14);p.mission.group=0;p.mission.assembly_count=1+w.self.id%6;return p;}
int main(){Geometry geo;Memory memory;std::unique_ptr<World>ptr;bool done=false;while(true){if(bc::is_draft()){auto old=bc::draft::current_draft(bc::team::ally);for(auto pick:{bc::champion_draft::ryth,bc::champion_draft::varg,bc::champion_draft::willow})if(std::find(old.begin(),old.end(),pick)==old.end()){bc::draft::pick(pick);break;}}else if(!done&&bc::detail::sdk_my_team()==0){if(!geo.initialized){geo.initialize();bc::end_turn();continue;}if(!ptr)ptr=std::make_unique<World>(geo,memory);auto&w=*ptr;w.refresh();auto p=selected(w);CrewTurnReceipt r;auto before=bc::fuel_remaining();r=make_crew_turn_receipt(w,p);auto after=bc::fuel_remaining();std::printf("NONCREW18 actor=%d nativeCost=%u valid=%d required=%d\n",w.self.id,unsigned(before-after),r.valid,r.required);before=bc::fuel_remaining();if(p.crew_clear_certified)r=make_crew_turn_receipt(w,p);else{r.valid=false;r.required=false;}after=bc::fuel_remaining();std::printf("NONCREW18_GATED actor=%d nativeCost=%u valid=%d required=%d\n",w.self.id,unsigned(before-after),r.valid,r.required);done=true;}bc::end_turn();}}
